 +'<section id="mission-guide" class="mission-guide" aria-live="polite"><div class="guide-row"><span class="mission-icon">'+svg(safe?'flag':'attackmove')+'</span><div class="guide-copy"><small id="mission-kicker">CURRENT OBJECTIVE</small><strong id="mission-title">Secure your first relay</strong><p id="mission-text">Select a squad, then tap a neutral relay.</p></div><b class="mission-progress" id="mission-progress">0 / 3</b><button id="guide-dismiss" class="guide-close" aria-label="Collapse objective">'+svg('clear')+'</button></div><div id="tutorial-card" class="tutorial-card hidden"></div></section>'
 +(safe?'<div id="prep-banner" class="prep-banner" hidden><span class="prep-clock"><b id="prep-clock">02:00</b><small>PREPARE YOUR DEFENSES</small></span><button id="begin-defense" class="begin-defense" disabled>'+svg('play')+'<span><strong>Begin Defense</strong><small id="begin-detail">Protected</small></span></button></div>':'')
 +'<div id="wave-alert" class="wave-alert" hidden>'+svg('warning')+'<span><strong id="wave-title">Hostiles approaching</strong><small id="wave-detail">From the east road</small></span></div>'
 +'<aside id="intel-panel" class="intel-panel" hidden><div class="panel-title"><span>'+(safe?'MISSION STATUS':'VICTORY STATUS')+'</span><strong id="points">0–0</strong></div><div id="objectives"></div><div class="supply-caption"><span>Army capacity</span><b id="supply-copy">0 / 50</b></div><div class="supplybar"><div id="supplybar"></div></div><div class="panel-title"><span>BATTLE FEED</span></div><div class="feed" id="feed"></div></aside>'
 +'<div class="view-controls" aria-label="Camera"><button id="zoom-in" class="icon-btn" aria-label="Zoom in">+</button><button id="zoom-out" class="icon-btn" aria-label="Zoom out">−</button><button id="view-mode" class="icon-btn wide-only" aria-label="Toggle 2D tactical map">2D</button></div>'
 +'<footer class="hud-bottom"><section class="hud-bl command-dock">'+dockMarkup()+'</section><section class="hud-br selection-tray"><div class="selection-summary"><span class="selection-orb"></span><span><small>SELECTED</small><strong id="selection-summary">Nothing</strong></span></div><div class="commandbar">'+actionButton('id="select-all"','all','All','Q')+actionButton('data-action="move"','move','Move','M')+actionButton('data-action="attackmove"','attackmove','Attack','A')+actionButton('data-action="hold"','hold','Hold','H')+actionButton('data-action="orbital"','orbital','Strike','B')+actionButton('id="box-select"','box','Box','')+actionButton('id="deselect"','clear','Clear','Esc')+'</div></section></footer>'
 +'<div id="gesture-hand" class="gesture-hand" hidden><i class="finger"></i><i class="ring"></i></div>'
 +'<div id="menu-sheet" class="menu-sheet" hidden><section class="panel menu-panel"><small>'+(safe?'OPERATION SAFE HAVEN':MAPS.get(game.mapId).name.toUpperCase())+(game.mode==='pvp'?' · ROOM '+escapeHTML(room):'')+'</small><h2>Paused</h2><button id="menu-close" class="play-btn compact">'+svg('play')+'<span><strong>Resume</strong></span></button><button id="menu-view" class="ghost-btn wide">Switch to 2D tactical map</button><div id="menu-quality-slot"></div>'+(safe?'<button id="menu-tutorial" class="ghost-btn wide">Replay field training</button>':'')+'<button id="surrender" class="ghost-btn wide danger">Surrender</button><div id="surrender-confirm-row" class="confirm-row" hidden><span>Abandon this battle?</span><button id="surrender-confirm" class="ghost-btn danger">Surrender</button><button id="surrender-cancel" class="ghost-btn">Keep fighting</button></div><button id="menu-exit" class="ghost-btn wide">Exit to menu</button></section></div>'
