function placementCheck(point,type){if(!point||!STRUCTURES[type]||point.x==null)return {ok:false,reason:'Tap a clear location'};const radius=STRUCTURES[type].radius,bounds=game.world?.bounds||{left:125,right:2275,top:105,bottom:1245};if(!(point.x>bounds.left+45&&point.x<bounds.right-45&&point.y>bounds.top+45&&point.y<bounds.bottom-45))return {ok:false,reason:'Outside the town boundary'};const engineers=game.units.filter(unit=>unit.team===team&&unit.type==='engineer'&&selected.has(unit.id));if(engineers.length&&Math.min(...engineers.map(e=>distance(e,point)))>390)return {ok:false,reason:'Too far from your engineer'};const blockers=[...(game.bases||[]),...(game.facilities||[]),...(game.structures||[]),...(game.nodes||[])];if(blockers.some(object=>object.hp!==0&&distance(object,point)<(object.radius||44)+radius+18))return {ok:false,reason:'Too close to another building'};if(MAPS.blockers(game.mapId).some(object=>distance(object,point)<object.radius+radius+10))return {ok:false,reason:'Blocked by homes or market stalls'};return {ok:true,reason:'Clear site'}}
function placementValid(point,type){return placementCheck(point,type).ok}
function updatePlacementUI(){const panel=$('#placement-panel');if(!panel)return;panel.classList.toggle('hidden',!placement);if(!placement){window.Iron3D?.sync(game,selected);return}const check=placementCheck(placement,placement.type),item=STRUCTURES[placement.type];hudText('#placement-meta',item.label.toUpperCase()+' · '+item.cost+' CR · '+item.time+'s');hudText('#placement-name',placement.x==null?'Tap a clear site near your engineer':check.reason);$('#confirm-placement').disabled=!check.ok||!placement.locked;panel.classList.toggle('invalid',placement.x!=null&&!check.ok);panel.classList.toggle('valid',placement.x!=null&&check.ok);window.Iron3D?.sync(game,selected)}
