 if(step==='cache'){const c=(game.caches||[]).filter(v=>v.claimedBy===null).sort((a,b)=>distance(a,{x:400,y:600})-distance(b,{x:400,y:600}))[0];return c?{kind:'tap',world:c}:null}
 if(step==='defense')return game.mission?.stage==='prepare'?{...el('#begin-defense'),kind:'tap'}:null;
